-- WAKILISHA RNB18 historic replay repair, Stage 1 canonical forward migration.
-- Exact filename generated by official Supabase CLI 2.107.0 in GitHub Actions
-- run 41349990017, recorded at 2026-11-01 21:03:35 UTC.
-- Body is byte-identical to the Stage 1 v4 candidate accepted on real isolated
-- PostgreSQL 17 (run 41349597513), with read-only existing Production assertions.
-- Original installed 20261030062819 retirement migration and recovery archive
-- remain untouched. This file is the forward schema-authority repair only.
-- Rollout gated: do not apply to Production until exact-head review, migration
-- history preflight and independently accepted promotion authorization.
BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

DO $rnb18_stage1$
DECLARE
    v_rows_exists boolean;
    v_receipt_exists boolean;
    v_archive_existing boolean;
    v_status_before text;
    v_status_after text;
    v_status_actual text;
    v_name text;
    v_expected_columns jsonb;
    v_actual_columns jsonb;
    v_expected_constraints jsonb;
    v_actual_constraints jsonb;
    v_expected_triggers jsonb;
    v_actual_triggers jsonb;
    v_table regclass;
    v_rel record;
    v_fn record;
    v_count bigint;
    v_digest text;
    v_receipt_digest text;
BEGIN
    IF to_regnamespace('platform_private') IS NULL OR
       to_regclass('public.chart_ingest_runs') IS NULL THEN
        RAISE EXCEPTION 'rnb18_stage1_required_baseline_missing';
    END IF;

    v_rows_exists := to_regclass('platform_private.wk_chart_rnb18_retirement_rows_20261030') IS NOT NULL;
    v_receipt_exists := to_regclass('platform_private.wk_chart_rnb18_retirement_receipt_20261030') IS NOT NULL;
    IF v_rows_exists <> v_receipt_exists THEN
        RAISE EXCEPTION 'rnb18_stage1_partial_archive_authority_refused';
    END IF;
    v_archive_existing := v_rows_exists;

    v_status_before := 'CHECK (status = ANY (ARRAY[' ||
      '''draft''::text, ''queued''::text, ''running''::text, ''preflight_passed''::text, ' ||
      '''fetching''::text, ''normalizing''::text, ''scoring''::text, ''reviewing''::text, ' ||
      '''commit_pending''::text, ''dry_run_complete''::text, ''ready_to_commit''::text, ' ||
      '''committing''::text, ''committed''::text, ''needs_review''::text, ' ||
      '''publishing''::text, ''published''::text, ''failed''::text, ''cancelled''::text, ' ||
      '''source_fetch_failed''::text]))';
    v_status_after := replace(v_status_before,
      '''source_fetch_failed''::text]))',
      '''source_fetch_failed''::text, ''retired''::text]))');

    SELECT pg_get_constraintdef(c.oid, true) INTO v_status_actual
      FROM pg_constraint c
     WHERE c.conrelid = 'public.chart_ingest_runs'::regclass
       AND c.conname = 'chart_ingest_runs_status_check'
       AND c.contype = 'c';
    IF v_status_actual IS NULL OR
       v_status_actual NOT IN (v_status_before, v_status_after) THEN
        RAISE EXCEPTION 'rnb18_stage1_unrecognized_ingest_status_constraint';
    END IF;
    IF v_archive_existing AND v_status_actual <> v_status_after THEN
        RAISE EXCEPTION 'rnb18_stage1_existing_archive_requires_retired_status';
    END IF;
    IF NOT v_archive_existing AND v_status_actual <> v_status_before THEN
        RAISE EXCEPTION 'rnb18_stage1_fresh_archive_requires_original_status';
    END IF;

    -- The normal fresh replay path. Never manufacture Edition/Entry evidence.
    IF NOT v_archive_existing THEN
        EXECUTE $create$
            CREATE TABLE platform_private.wk_chart_rnb18_retirement_rows_20261030 (
                object_kind text NOT NULL,
                row_key text NOT NULL,
                payload jsonb NOT NULL,
                payload_sha256 text NOT NULL
                    CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
                archived_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                PRIMARY KEY (object_kind, row_key)
            )
        $create$;
        EXECUTE $create$
            CREATE TABLE platform_private.wk_chart_rnb18_retirement_receipt_20261030 (
                batch_key text PRIMARY KEY,
                issue_number int NOT NULL,
                edition_count int NOT NULL,
                entry_count int NOT NULL,
                archived_row_count int NOT NULL,
                archive_sha256 text NOT NULL
                    CHECK (archive_sha256 ~ '^[0-9a-f]{64}$'),
                archived_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                notes text NOT NULL
            )
        $create$;
        EXECUTE 'ALTER TABLE platform_private.wk_chart_rnb18_retirement_rows_20261030 OWNER TO postgres';
        EXECUTE 'ALTER TABLE platform_private.wk_chart_rnb18_retirement_receipt_20261030 OWNER TO postgres';
        EXECUTE 'REVOKE ALL ON platform_private.wk_chart_rnb18_retirement_rows_20261030 FROM PUBLIC, anon, authenticated, service_role';
        EXECUTE 'REVOKE ALL ON platform_private.wk_chart_rnb18_retirement_receipt_20261030 FROM PUBLIC, anon, authenticated, service_role';
        EXECUTE 'ALTER TABLE platform_private.wk_chart_rnb18_retirement_rows_20261030 ENABLE ROW LEVEL SECURITY';
        EXECUTE 'ALTER TABLE platform_private.wk_chart_rnb18_retirement_receipt_20261030 ENABLE ROW LEVEL SECURITY';

        EXECUTE $create$
            CREATE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()
            RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog
            AS $body$
            begin
              raise exception 'rnb18_archive_immutable';
            end
            $body$
        $create$;
        EXECUTE 'ALTER FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030() OWNER TO postgres';
        EXECUTE 'REVOKE ALL ON FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030() FROM PUBLIC, anon, authenticated, service_role';
        EXECUTE $create$
            CREATE TRIGGER trg_wk_rnb18_rows_immutable_update_delete
            BEFORE UPDATE OR DELETE ON platform_private.wk_chart_rnb18_retirement_rows_20261030
            FOR EACH ROW EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()
        $create$;
        EXECUTE $create$
            CREATE TRIGGER trg_wk_rnb18_rows_immutable_truncate
            BEFORE TRUNCATE ON platform_private.wk_chart_rnb18_retirement_rows_20261030
            FOR EACH STATEMENT EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()
        $create$;
        EXECUTE $create$
            CREATE TRIGGER trg_wk_rnb18_receipt_immutable_update_delete
            BEFORE UPDATE OR DELETE ON platform_private.wk_chart_rnb18_retirement_receipt_20261030
            FOR EACH ROW EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()
        $create$;
        EXECUTE $create$
            CREATE TRIGGER trg_wk_rnb18_receipt_immutable_truncate
            BEFORE TRUNCATE ON platform_private.wk_chart_rnb18_retirement_receipt_20261030
            FOR EACH STATEMENT EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()
        $create$;
        EXECUTE 'ALTER TABLE public.chart_ingest_runs DROP CONSTRAINT chart_ingest_runs_status_check';
        EXECUTE 'ALTER TABLE public.chart_ingest_runs ADD CONSTRAINT chart_ingest_runs_status_check CHECK (status = ANY (ARRAY[' ||
           '''draft'', ''queued'', ''running'', ''preflight_passed'', ''fetching'', ' ||
           '''normalizing'', ''scoring'', ''reviewing'', ''commit_pending'', ' ||
           '''dry_run_complete'', ''ready_to_commit'', ''committing'', ''committed'', ' ||
           '''needs_review'', ''publishing'', ''published'', ''failed'', ' ||
           '''cancelled'', ''source_fetch_failed'', ''retired'' ]::text[]))';
    END IF;

    -- Validate the exact Production authority, including columns and defaults.
    FOR v_name, v_expected_columns, v_expected_constraints, v_expected_triggers IN
      SELECT * FROM (VALUES
        (
          'wk_chart_rnb18_retirement_rows_20261030',
          '[ ["object_kind","text",true,null], ["row_key","text",true,null], ["payload","jsonb",true,null], ["payload_sha256","text",true,null], ["archived_at","timestamp with time zone",true,"clock_timestamp()"] ]'::jsonb,
          '[ ["wk_chart_rnb18_retirement_rows_20261030_payload_sha256_check","CHECK (payload_sha256 ~ ''^[0-9a-f]{64}$''::text)"], ["wk_chart_rnb18_retirement_rows_20261030_pkey","PRIMARY KEY (object_kind, row_key)"] ]'::jsonb,
          '[ ["trg_wk_rnb18_rows_immutable_truncate","O","CREATE TRIGGER trg_wk_rnb18_rows_immutable_truncate BEFORE TRUNCATE ON platform_private.wk_chart_rnb18_retirement_rows_20261030 FOR EACH STATEMENT EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()"], ["trg_wk_rnb18_rows_immutable_update_delete","O","CREATE TRIGGER trg_wk_rnb18_rows_immutable_update_delete BEFORE DELETE OR UPDATE ON platform_private.wk_chart_rnb18_retirement_rows_20261030 FOR EACH ROW EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()"] ]'::jsonb
        ),
        (
          'wk_chart_rnb18_retirement_receipt_20261030',
          '[ ["batch_key","text",true,null], ["issue_number","integer",true,null], ["edition_count","integer",true,null], ["entry_count","integer",true,null], ["archived_row_count","integer",true,null], ["archive_sha256","text",true,null], ["archived_at","timestamp with time zone",true,"clock_timestamp()"], ["notes","text",true,null] ]'::jsonb,
          '[ ["wk_chart_rnb18_retirement_receipt_20261030_archive_sha256_check","CHECK (archive_sha256 ~ ''^[0-9a-f]{64}$''::text)"], ["wk_chart_rnb18_retirement_receipt_20261030_pkey","PRIMARY KEY (batch_key)"] ]'::jsonb,
          '[ ["trg_wk_rnb18_receipt_immutable_truncate","O","CREATE TRIGGER trg_wk_rnb18_receipt_immutable_truncate BEFORE TRUNCATE ON platform_private.wk_chart_rnb18_retirement_receipt_20261030 FOR EACH STATEMENT EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()"], ["trg_wk_rnb18_receipt_immutable_update_delete","O","CREATE TRIGGER trg_wk_rnb18_receipt_immutable_update_delete BEFORE DELETE OR UPDATE ON platform_private.wk_chart_rnb18_retirement_receipt_20261030 FOR EACH ROW EXECUTE FUNCTION platform_private.wk_chart_rnb18_archive_immutable_20261030()"] ]'::jsonb
        )
      ) AS expected(name, columns, constraints, triggers)
    LOOP
        v_table := to_regclass('platform_private.' || v_name);
        SELECT c.relkind, c.relrowsecurity, c.relforcerowsecurity,
               pg_get_userbyid(c.relowner) AS owner_name, c.relacl::text AS acl
          INTO v_rel FROM pg_class c WHERE c.oid = v_table;
        IF v_rel.relkind IS DISTINCT FROM 'r' OR
           v_rel.relrowsecurity IS DISTINCT FROM true OR
           v_rel.relforcerowsecurity IS DISTINCT FROM false OR
           v_rel.owner_name IS DISTINCT FROM 'postgres' OR
           v_rel.acl IS DISTINCT FROM '{postgres=arwdDxtm/postgres}' THEN
            RAISE EXCEPTION 'rnb18_stage1_relation_owner_rls_acl_mismatch:%',v_name;
        END IF;

        SELECT jsonb_agg(jsonb_build_array(a.attname,
                  format_type(a.atttypid,a.atttypmod),a.attnotnull,
                  pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum)
          INTO v_actual_columns
          FROM pg_attribute a
          LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
         WHERE a.attrelid=v_table AND a.attnum>0 AND NOT a.attisdropped;
        IF v_actual_columns IS DISTINCT FROM v_expected_columns THEN
            RAISE EXCEPTION 'rnb18_stage1_archive_column_mismatch:%',v_name;
        END IF;

        SELECT jsonb_agg(jsonb_build_array(conname,pg_get_constraintdef(oid,true)) ORDER BY conname)
          INTO v_actual_constraints FROM pg_constraint WHERE conrelid=v_table;
        IF v_actual_constraints IS DISTINCT FROM v_expected_constraints THEN
            RAISE EXCEPTION 'rnb18_stage1_archive_constraint_mismatch:%',v_name;
        END IF;

        SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid,true)) ORDER BY tgname)
          INTO v_actual_triggers FROM pg_trigger WHERE tgrelid=v_table AND NOT tgisinternal;
        IF v_actual_triggers IS DISTINCT FROM v_expected_triggers THEN
            RAISE EXCEPTION 'rnb18_stage1_archive_trigger_mismatch:%',v_name;
        END IF;
    END LOOP;

    SELECT p.prorettype='trigger'::regtype AS return_is_trigger,
           p.prosecdef, p.proacl::text AS acl, pg_get_userbyid(p.proowner) AS owner_name,
           l.lanname AS language_name, p.proconfig,
           btrim(regexp_replace(p.prosrc, '[[:space:]]+', ' ', 'g')) AS body
      INTO v_fn
      FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
     WHERE p.oid=to_regprocedure('platform_private.wk_chart_rnb18_archive_immutable_20261030()');
    IF v_fn.return_is_trigger IS DISTINCT FROM true OR
       v_fn.prosecdef IS DISTINCT FROM false OR
       v_fn.acl IS DISTINCT FROM '{postgres=X/postgres}' OR
       v_fn.owner_name IS DISTINCT FROM 'postgres' OR
       v_fn.language_name IS DISTINCT FROM 'plpgsql' OR
       v_fn.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog']::text[] OR
       v_fn.body IS DISTINCT FROM 'begin raise exception ''rnb18_archive_immutable''; end' THEN
        RAISE EXCEPTION 'rnb18_stage1_immutability_function_mismatch';
    END IF;

    SELECT pg_get_constraintdef(c.oid,true) INTO v_status_actual
      FROM pg_constraint c
     WHERE c.conrelid='public.chart_ingest_runs'::regclass
       AND c.conname='chart_ingest_runs_status_check' AND c.contype='c';
    IF v_status_actual IS DISTINCT FROM v_status_after THEN
        RAISE EXCEPTION 'rnb18_stage1_retired_status_contract_mismatch';
    END IF;

    -- On a new database there must be zero fabricated historical data.
    IF NOT v_archive_existing THEN
        EXECUTE 'SELECT count(*) FROM platform_private.wk_chart_rnb18_retirement_rows_20261030' INTO v_count;
        IF v_count <> 0 THEN RAISE EXCEPTION 'rnb18_stage1_fresh_rows_nonempty'; END IF;
        EXECUTE 'SELECT count(*) FROM platform_private.wk_chart_rnb18_retirement_receipt_20261030' INTO v_count;
        IF v_count <> 0 THEN RAISE EXCEPTION 'rnb18_stage1_fresh_receipt_nonempty'; END IF;
        RAISE NOTICE 'RNB18_STAGE1_FRESH_AUTHORITY_CREATED_EMPTY';
    ELSE
        SELECT count(*), encode(extensions.digest(string_agg(object_kind||':'||row_key||':'||payload_sha256,E'\n' ORDER BY object_kind,row_key),'sha256'),'hex')
          INTO v_count, v_digest
          FROM platform_private.wk_chart_rnb18_retirement_rows_20261030;
        IF v_count <> 2904 THEN RAISE EXCEPTION 'rnb18_stage1_archive_row_count_mismatch:%',v_count; END IF;
        SELECT count(*) INTO v_count FROM platform_private.wk_chart_rnb18_retirement_rows_20261030
         WHERE payload_sha256 <> encode(extensions.digest(payload::text,'sha256'),'hex');
        IF v_count <> 0 THEN RAISE EXCEPTION 'rnb18_stage1_archive_digest_corrupt:%',v_count; END IF;
        SELECT archive_sha256 INTO v_receipt_digest
          FROM platform_private.wk_chart_rnb18_retirement_receipt_20261030
         WHERE batch_key='rnb18-20261030' AND issue_number=1326
           AND edition_count=18 AND entry_count=1800 AND archived_row_count=2904;
        IF v_receipt_digest IS NULL OR v_receipt_digest <> v_digest OR
           (SELECT count(*) FROM platform_private.wk_chart_rnb18_retirement_receipt_20261030) <> 1 THEN
            RAISE EXCEPTION 'rnb18_stage1_archive_receipt_mismatch';
        END IF;
        RAISE NOTICE 'RNB18_STAGE1_EXISTING_ARCHIVE_ASSERTED_UNCHANGED';
    END IF;
END
$rnb18_stage1$;

COMMIT;
